        startedAt,
        measured: { ...measured, laws: wanted.join(","), cancelled },
        summary: {
          en: `reopen storm laws ${wanted.length - failed.length}/${wanted.length} pass (${wanted.join(", ")})${failed.length ? `; failing: ${failed.join(", ")}` : ""}${cancelled ? "; cancelled" : ""}`,
