    for (const row of fixture.committedRecovery.cases) {
      const expected = row.frontier === "base" ? ["complete", 3] : row.frontier === "post" ? ["already-applied", 0] : ["fault", 0];
      assert.deepEqual([row.expected, row.mutations], expected);
